:root { font-family: system-ui, sans-serif; }
* { box-sizing: border-box; }
body { display: grid; min-height: 100vh; margin: 0; place-items: center; padding: 20px; color: #ffffff; transition: background .45s; }
.work-mode { background: linear-gradient(135deg, #b91c1c, #c2410c); }
.rest-mode { background: linear-gradient(135deg, #047857, #0e7490); }
.pomodoro { width: min(100%, 520px); padding: clamp(28px, 7vw, 52px); border-radius: 26px; background: rgba(15,23,42,.2); text-align: center; backdrop-filter: blur(10px); }
.pomodoro h1 { margin: 0; font-size: 1rem; letter-spacing: .1em; text-transform: uppercase; }
.mode { margin: 24px 0 10px; font-size: 1.3rem; font-weight: 700; }
.time { display: block; margin-bottom: 30px; font-size: clamp(4.5rem, 20vw, 8rem); font-weight: 250; line-height: 1; font-variant-numeric: tabular-nums; }
.actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; }
button { min-width: 120px; min-height: 46px; padding: 12px 24px; border: 0; border-radius: 999px; color: #0f172a; background: #ffffff; font: inherit; font-weight: 800; cursor: pointer; }
button.secondary { color: #ffffff; background: rgba(255,255,255,.18); }
button:focus-visible { outline: 3px solid #fde68a; outline-offset: 3px; }
.cycles { margin: 24px 0 0; color: #fef3c7; }
@media (prefers-reduced-motion: reduce) { body { transition: none; } }

const workSeconds = 25 * 60;
const restSeconds = 5 * 60;
let mode = 'work';
let secondsLeft = workSeconds;
let timerId = null;
let completed = 0;
const modeElement = document.querySelector('#mode');
const timeElement = document.querySelector('#time');
const toggle = document.querySelector('#toggle');
const cycles = document.querySelector('#cycles');

function render() {
  const minutes = Math.floor(secondsLeft / 60);
  const seconds = secondsLeft % 60;
  timeElement.textContent = String(minutes).padStart(2, '0') + ':' + String(seconds).padStart(2, '0');
  timeElement.dateTime = 'PT' + minutes + 'M' + seconds + 'S';
  modeElement.textContent = mode === 'work' ? '专注工作' : '短暂休息';
  document.body.className = mode === 'work' ? 'work-mode' : 'rest-mode';
}

function switchMode() {
  if (mode === 'work') {
    completed++;
    cycles.textContent = '已完成 ' + completed + ' 个番茄';
    mode = 'rest';
    secondsLeft = restSeconds;
  } else {
    mode = 'work';
    secondsLeft = workSeconds;
  }
  render();
}

function tick() {
  if (secondsLeft === 0) switchMode(); else { secondsLeft--; render(); }
}

toggle.addEventListener('click', () => {
  if (timerId) {
    window.clearInterval(timerId);
    timerId = null;
    toggle.textContent = '继续';
  } else {
    timerId = window.setInterval(tick, 1000);
    toggle.textContent = '暂停';
  }
});
document.querySelector('#reset').addEventListener('click', () => {
  window.clearInterval(timerId);
  timerId = null;
  mode = 'work';
  secondsLeft = workSeconds;
  completed = 0;
  cycles.textContent = '已完成 0 个番茄';
  toggle.textContent = '开始';
  render();
});
render();
